reactions.evaluate:
switch (triggerType) {
    case "onTurnEnd":
        // We have to check here early otherwise the suppression will have 
        // already been removed by the time the activation code runs.
        return ! api.findEffectOnToken(reactorToken, "Regeneration Suppression");
    default:
        return true;
}

reactions.activationCode:
switch (triggerType) {
    // If we are suppressed, this will not fire since the evaluation will skip it.
    case 'onTurnEnd': {
        const actor = reactorToken.actor;
        const { value: hpCur, max: hpMax } = actor.system.hp;
        const hpMissing = hpMax - hpCur

        if (hpMissing <= 0) break; // Nothing to regenerate

        // this is the divisor for the regen, so half (2.0) when core is active, a quarter (4.0) otherwise.
        const regenFactor = api.hasStatus(reactorToken, 'core_power_active') ? 2 : 4;
        const regen = Math.min(Math.ceil(hpMax / regenFactor), hpMissing);

        actor.modifyTokenAttribute('hp', regen, true, true); // no need to await this
        ChatMessage.create({
            speaker: ChatMessage.getSpeaker({ actor }),
            content: `<b>${actor.name}</b> regenerated ${regen} ${game.i18n.localize('lancer.common-sheet.shortStats.hp')}.`
        });
        break;
    }
    case 'onStructure':
    case 'onStress':
        api.applyEffectsToTokens(
            {
                tokens: [reactorToken],
                effectNames: {name: 'Regeneration Suppression', icon: 'modules/lancer-automations/icons/pause-button.svg', isCustom: true},
                note: 'Suppresses end of turn Balor regeneration',
                duration: api.untilEndOfTurn(reactorToken),
                refresh: true
            }
        );
        break;
}

const actor = reactorToken.actor;
const { confirmed } = await api.askCard({
    title: 'Balor Self-Perpetuating',
    description: `${actor.name} may regenerate full HP without spending repairs if you rest.`,
    yesText: 'Rest',
    yesIcon: 'fas fa-first-aid',
    noText: 'No Rest',
    owner: reactorToken,
    originToken: reactorToken
});

if (confirmed){
    await actor.update({ 'system.hp.value': actor.system.hp.max });
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor }),
        content: `<b>${actor.name}</b> regenerates all HP via Self-Perpetuating.`
    });
}

const turnTokenId = triggerData.triggeringToken.id
const turnActorId = triggerData.triggeringToken.actor.uuid;

// Collect any tokens including deployables in range 1 that are the triggering token, or owned by the triggering token
let adjacentTokens = api.getTokensInRange(
    reactorToken, 
    {
        range: 1,
        includeHidden: true,
        includeDeployables: true,
        includeElevation: true,
        filter: (token) => (token.id === turnTokenId || token.document.getFlag('lancer-automations', 'ownerActorUuid') === turnActorId),
    }
);

if (adjacentTokens.length < 1) return;

let core = api.hasStatus(reactorToken, 'core_power_active')? 4 : 2;
await api.executeDamageRoll(reactorToken, adjacentTokens, core, 'kinetic', 'Scouring Swarm');
